<?php require __DIR__.'/runtime_bootstrap.php';$role=$argv[1];$f=json_decode(file_get_contents(__DIR__.'/race-proposal.private.json'),true);try{$r=app(App\Services\SlowDatingService::class)->decision($f[$role]['id'],$f['proposal']['id'],'accept',1,'concurrent-'.$role);echo json_encode(['role'=>$role,'status'=>200,'state'=>$r['state']]);}catch(Symfony\Component\HttpKernel\Exception\HttpException $e){echo json_encode(['role'=>$role,'status'=>$e->getStatusCode(),'message'=>$e->getMessage()]);}catch(Throwable $e){fwrite(STDERR,get_class($e).':'.$e->getMessage());exit(1);}
